function UICultivateEquipUpgradeLevelDialog:InitData()

    local argument = self.controller.Argument.parameters
    local equipId = checkNumber(argument.equipId)
    KCookie.Set(Constants.UICacheDataKeys.UIJumpExAttachParams, {excludeId = equipId})
    self:SetPlayerEquipId(equipId)

    self:InitFastSelectRule()

    ---@type EquipDojo
    local equipDojo = equipComp:GetEquipById(equipId)
    self:SetEquipDojo(equipDojo)

    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    self.maxLevel = cardConfMgr:GetEquipMaxLevelByQuality(equipVo.rare)
    self.maxLevelExp = cardConfMgr:GetEquipExpByLevelId(equipVo.levelUpType, equipVo.rare, self.maxLevel)
    self.consumeAspect = GameUtils.GetConsumeAspect(Constants.UpGradeConsume.EquipConsume)
    self.equipPart = equipVo.part

    self:UpdateData(equipDojo, equipVo)

    self.equipVo = equipVo

end

function UICultivateEquipUpgradeLevelDialog:InitFastSelectRule()
    local ruleStr = CfUtils.GetLocalData(self.fastSelectRuleKey, '')
    if not string.isEmpty(ruleStr) then
        self:RecoveryFastSelectRule(ruleStr)
        return self.fastSelectRule
    end
    local groups = {}
    local defMaxCondConf = {
        [Constants.EquipCultivateFastSelectFilterType.Quality] = Constants.QualityType.Blue,
        [Constants.EquipCultivateFastSelectFilterType.Part]    = Constants.EquipCultivateFilterPartType.Core,
        [Constants.EquipCultivateFastSelectFilterType.Food]    = Constants.EquipCultivateFoodType.DogFood,
    }
    local screenList = cardConfMgr:GetAllScreenVo(Constants.UIFilterType.EquipCultivateFastSelect)
    ---@param v ScreenVo
    for i, v in ipairs(screenList) do
        local id = v.id
        groups[id] = groups[id] or {}
        local maxCond = defMaxCondConf[id]
        ---@param cond number
        for _, cond in pairs(v.condition) do
            cond = checkNumber(cond)
            if maxCond == nil or (cond <= maxCond) then
                table.insert(groups[id], checkNumber(cond))
            end
        end
    end

    self.fastSelectRule = groups
end

