function UICultivateEquipUpgradeLevelDialog:InitSubAttributes(equipDojo, oldEquipDojo)
    local equipVo = self.equipVo
    ---@type EquipQualityVo
    local equipQualityVo = cardConfMgr:GetEquipQualityVoByRefId(equipVo.rare)
    local maxNum         = equipQualityVo.maxNum
    local subAttributes  = {}
    local overMax        = equipQualityVo.overMax
    local baseLv         = equipQualityVo.baseLv
    local baseAttrCount  = self.baseAttrCount
    for i = 1, maxNum do
        local attrAdditionId = checkNumber(equipDojo[string.format("attr%sId", i)])
        local isOwnAttr = attrAdditionId > 0
        local data = {
            attrAdditionId = attrAdditionId
        }
        if isOwnAttr then
            local attrNumKey = string.format("attr%sNum", i)
            local attrNum = equipDojo[attrNumKey]
            local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)

            data.attributeName = tostring(attrAdditionVo.attrAdditionName)
            data.attributeNum = attrNum

            if oldEquipDojo then
                data.additionNum = attrNum - oldEquipDojo[attrNumKey]
            end

        else
            local unlockAttrLevel = baseLv + overMax * (i - baseAttrCount)
            data.unlockAttrLevel = unlockAttrLevel
            data.isCanUnlock = self.nextLevel >= unlockAttrLevel
        end

        table.insert(subAttributes, data)

        if not isOwnAttr and self.nextUnlockAttrIndex == nil then
            self.nextUnlockAttrIndex = i
        end
    end
    self.subAttributes = subAttributes
end

---RefreshEquipBackpack
---刷新装备背包
function UICultivateEquipUpgradeLevelDialog:InitEquipBackpack()

    ---@type UICultivateEquipLevelBackpackNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
    if mbEnv == nil then return end
    local playerEquipId = checkNumber(self:GetPlayerEquipId())
    mbEnv:InitData(0, self.equipPart, playerEquipId)
    mbEnv:SetClickCellAction(Bind(self, self.UpdateEquipExp))
    mbEnv:SetMaxSelectCount(MaxSelectCount)
    mbEnv:SetCellLongTapCallback(function(id, compareId, equipType, part)
        local curDojo, compareDojo
        if equipType == EQUIP_TYPE.Core then
            curDojo = equipComp:GetEquipCoreById(id)
            compareDojo = equipComp:GetEquipCoreById(compareId)
        elseif equipType == EQUIP_TYPE.Equip then
            curDojo = equipComp:GetEquipById(id)
            compareDojo = equipComp:GetEquipById(compareId)
        end
        self:LoadComparedView(curDojo, compareDojo, equipType, part)
    end)

    mbEnv:SetClickCellCheckCallback(function ()
        ---@type EquipDojo
        local equipDojo = self:GetEquipDojo()
        if checkNumber(equipDojo.level) >= self.maxLevel then
            GameUtils.Toast(localize("已到达最大等级"))
            return false
        end
        if self.arrivalsMaxLvNeedExp <= 0 then
            GameUtils.Toast(localize("已能到达最大等级"))
            return false
        end
        return true
    end)
end


