function UICultivateEquipUpgradeLevelDialog:InitSettingPanel()
    ---@type UICultivateEquipSettingPanel
    local env = CfUtils.GetLuaScr(self.SettingPanel, SetPanelEnvPath)
    if isNull(env) then return end
    env:FreshUI(Constants.UIFilterType.EquipCultivateFastSelect, self.fastSelectRule)
    env:SetLeftBtnClickCallback(function(luaEnv)
        luaEnv:CloseView()
        self.isShowSetting = false
    end)
    env:SetRightBtnClickCallback(Bind(self, self.OnFastSelectAction))
    env:FreshMinAndMaxLv(math.min(self.nextLevel + 1, self.maxLevel), self.maxLevel)
end


function UICultivateEquipUpgradeLevelDialog:InitDogFood()
    if next(self.dogFoodNodes) then return end
    local part     = self.equipPart
    ---@type EquipmentDogFoodVo[]
    local dogFoods = EquipUtils.GetEquipmentDogFoodVosByPart(part)

    local parent   = self.Layout.gameObject
    local child    = self.Node.gameObject
    for i, v in ipairs(dogFoods) do
        local node = parent:AddChild(child)
        KTool.SetActive(node.gameObject, true)
        node.name = node.name .. i
        local data = {
            ownNum    = GoodsUtils.GetThingNo(v.id),
            selectNum = 0,
            dogFoodVo = v,
        }
        table.insert(self.dogFoodInfo, data)
        table.insert(self.dogFoodNodes, node)
        ---@type UICultivateEquipUpLevelDogFoodNode
        local env = CfUtils.GetLuaScr(node, DogFoodNodePath)
        if not isNull(env) then
            env:FreshUI(data, i)
            env:SetGoodNodeUpAction(Bind(self, self.OnGoodNodeUpAction))
            env:SetGoodNodeDownAction(Bind(self, self.OnGoodNodeDownAction))
            env:SetBtnReduceDownAction(Bind(self, self.OnBtnReduceDownAction))
            env:SetBtnReduceUpAction(Bind(self, self.OnBtnReduceUpAction))
        end
    end

    KTool.SetActive(child, false)
end

