function UICultivateEquipUpgradeLevelDialog:RefreshUI(isUpdate, oldEquipDojo)
    --------------------------
    --- get data

    ---@type EquipDojo
    local equipDojo = self:GetEquipDojo()
    --------------------------

    --------------------------
    --- update data
    if isUpdate then
        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
        self:UpdateData(equipDojo, equipVo)
    end
    --------------------------

    --------------------------
    --- refresh ui

    --- 刷新背包
    self:RefreshEquipBackpack()

    --- 刷新装备信息节点
    self:RefreshEquipExpInfo(equipDojo)

    --- 刷新装备属性节点
    self:RefreshEquipAttributeNode(equipDojo, oldEquipDojo)

    --- 刷新底部节点
    self:RefreshEquipBottomNode()

    local isMaxLevel = checkNumber(equipDojo.level) == self.maxLevel
    local styleId = isMaxLevel and "B16" or "B3"
    local text = isMaxLevel and localize("已满级") or localize("升级")
    self.UpgradeButton:ResetFontStyle(styleId, text)

    --------------------------
end

