---RefreshEquipInfoNode
---@param equipDojo EquipDojo
---@param factor number
function UICultivateEquipUpgradeLevelDialog:RefreshEquipExpInfo(equipDojo, factor)
    local value = self:CalcUpgradeLevelExp(equipDojo, factor)
    ---升级后下一级的总经验
    local equipVo              = self.equipVo
    local maxLevel             = self.maxLevel
    local nextLevel            = self.nextLevel
    local expAddition          = self.expAddition
    local currentLevel         = checkNumber(equipDojo.level)
    local level                = math.min(checkNumber(nextLevel) + 1, maxLevel)
    local levelUpType          = equipVo.levelUpType
    local rare                 = equipVo.rare
    local nextLevelExp         = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, level).exp
    local currentLevelTotalExp = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, currentLevel).totalExp
    ---当前等级下级等级经验
    level = math.min(currentLevel + 1, maxLevel)
    local curLvNextLevelExp = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, level).exp

    local isShowExpProgress = expAddition > 0
    local isShowFillArea = true
    if isShowExpProgress then
        self.ProgressBar.maxValue = nextLevelExp
        self.ProgressBar.value = value
        local exp = self.baseExp + expAddition - currentLevelTotalExp
        isShowFillArea = exp < curLvNextLevelExp
    end
    KTool.SetActive(self.FillArea.gameObject, isShowExpProgress)

    KTool.SetActive(self.ProLoad.gameObject, isShowFillArea)
    local isMaxLevel = currentLevel >= maxLevel
    if isShowFillArea then
        self.ProLoad.maxValue = curLvNextLevelExp
        --- 当前装备的经验 减去 当前等级的总经验
        self.ProLoad.value = isMaxLevel and curLvNextLevelExp or checkNumber(equipDojo.exp) - currentLevelTotalExp
    end

    self.LevelNumText2.text = currentLevel
    if isMaxLevel then
        -- self.LevelNumText.text = maxLevel
        KTool.SetActive(self.LevelNumText.gameObject,    false)
        KTool.SetActive(self.ArrowNode.gameObject,       false)
        KTool.SetActive(self.AdditionExpText.gameObject, false)
        
    else
        local isChange = expAddition > 0
        local status = isChange and 2 or 1
        self.ImgArrow1.Status = status
        self.ImgArrow2.Status = status
        if isChange then
            self.LevelNumText.text = string.format("<color=#ff4e9d><size=50>%s</size></color>/%s", nextLevel, maxLevel)
            self.AdditionExpText.text = string.format("<color=#ff4e9d>%s</color>/%s", checkInt(value), nextLevelExp)
        else
            self.LevelNumText.text = string.format("<size=50>%s</size>/%s", nextLevel, maxLevel)
            self.AdditionExpText.text = string.format("%s/%s", checkInt(value), nextLevelExp)
        end
    end
end

---EquipAttributeNode
---@param equipDojo EquipDojo
---@param oldEquipDojo EquipDojo
function UICultivateEquipUpgradeLevelDialog:RefreshEquipAttributeNode(equipDojo, oldEquipDojo)
    local equipVo = self.equipVo

    --------------------------
    ---刷新主属性
    local mainAttrType = equipDojo.mainAttrType
    ---@type EquipAttrVo
    local equipAttrVo = cardConfMgr:GetEquipAttrVoById(mainAttrType)
    local growNumConfig = equipAttrVo.attrNum[tostring(equipVo.rare)]
    local additionNum = (self.nextLevel - checkNumber(equipDojo.level)) * growNumConfig.growValue
    self:RefreshAttributeNode(equipDojo, additionNum)
    --------------------------

    --------------------------
    ---刷新副属性
    self:RefreshSubAttributeNode(equipDojo, oldEquipDojo)
    --------------------------
end

