---RefreshSubAttributeNode
---@param equipDojo    EquipDojo
---@param oldEquipDojo EquipDojo
function UICultivateEquipUpgradeLevelDialog:RefreshSubAttributeNode(equipDojo, oldEquipDojo)
    self:InitSubAttributes(equipDojo, oldEquipDojo)

    local count = #self.subAttributes
    local ScrollView = self.ScrollView
    local ScrollRect = ScrollView.ScrollRect
    
    if not ScrollView.IsListViewInit then
        self.ScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, count)
    end
    if not isNull(ScrollRect) then
        ScrollRect.vertical = false
    end
end

function UICultivateEquipUpgradeLevelDialog:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then return nil end
    local cell = listView:NewListViewItem(PrefabName)

    local cellViewMB = GetLuaBehaviour(cell.gameObject, EquipLevelAttributeNodePath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        if cellViewMB.Env == nil then
            cellViewMB:Init()
        end
    end

    ---@type UICultivateEquipLevelAttributeNode
    local mbEnv = cellViewMB.Env
    if mbEnv == nil then return end

    local attribute = self.subAttributes[index + 1]
    mbEnv:RefreshUI(
            attribute.attrAdditionId,
            attribute.attributeNum,
            attribute.additionNum,
            attribute.unlockAttrLevel,
            attribute.isCanUnlock
    )
    --mbEnv:RefreshAttrBgStatus(index % 2 ==  0 and 2 or 1)

    --local isActivation = false
    --if unlockAttrLevel then
    --    isActivation = self.nextLevel >= unlockAttrLevel
    --end

    return cell
end

