function UICultivateEquipUpgradeLevelDialog:LoadComparedView(curDojo, compareDojo, equipType, part)
    if self.ComparedView then
        self:RefreshComparedView(curDojo, compareDojo, equipType, part)
        return
    end
    if self.ComparedViewCo then
        return
    end
    self.ComparedViewCo = cs_coroutine.start(function()
        self.ComparedView = GameUtils.LoadBundleAsyncById(EquipComparedViewPrefabId, self.Container.gameObject, false, true)
        self:RefreshComparedView(curDojo, compareDojo, equipType, part)
        self.ComparedViewCo = nil
    end)
end

function UICultivateEquipUpgradeLevelDialog:StopComparedViewCo()
    if not isNull(self.ComparedViewCo) then
        cs_coroutine.stop(self.ComparedViewCo)
        self.ComparedViewCo = nil
    end
end

function UICultivateEquipUpgradeLevelDialog:RefreshComparedView(curDojo, compareDojo, equipType, part)
    ---@type UICultivateEquipComparedView
    local mbEnv = CfUtils.GetLuaScr(self.ComparedView, EquipComparedViewEnvPath)
    if not isNull(mbEnv) then
        mbEnv:RefreshEquipCultivateUI(curDojo, compareDojo, equipType, part)

        GameUtils.UpdateUIShowState(self.ComparedView.gameObject, true)
    end
end


