---CalcUpgradeLevelExp
---@param equipDojo EquipDojo
---@param factor number 因子
function UICultivateEquipUpgradeLevelDialog:CalcUpgradeLevelExp(equipDojo, factor)
    local equipVo = self.equipVo
    local curLevel = checkInt(equipDojo.level)
    local feedingTotalExp = self.baseExp + self.expAddition
    local levelUpType, rare = equipVo.levelUpType, equipVo.rare
    local curExp = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, curLevel)
    local deltaExp = feedingTotalExp - checkNumber(curExp.totalExp)
    if self.expAddition == 0 then
        self._isFullExp = false
        self.nextLevel = curLevel
        return deltaExp
    end

    local nextLevel = self.nextLevel or curLevel
    local maxLevel = self.maxLevel

    ---检查是否超过当前最大等级的经验
    local maxLevelExp = self.maxLevelExp
    if feedingTotalExp >= checkNumber(maxLevelExp.totalExp) then
        self._isFullExp = true
        nextLevel = maxLevel --当前星级的最大等级
        deltaExp = maxLevelExp.exp
    else
        local startIndex = factor > 0 and nextLevel or curLevel
        local endIndex = factor > 0 and maxLevel or math.min(nextLevel + 1, maxLevel)
        for lv = startIndex, endIndex do
            local totalExp = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, lv).totalExp
            if feedingTotalExp < totalExp then
                break
            end
            nextLevel = lv --可升级到的等级
        end

        self._isFullExp = false
        local tempTotalExp = cardConfMgr:GetEquipExpByLevelId(levelUpType, rare, nextLevel).totalExp

        ---升级后下一级的总经验
        deltaExp = feedingTotalExp - checkNumber(tempTotalExp)
    end
    self.nextLevel = nextLevel

    return deltaExp
end

---CalcEquipFoodExp
---@param backpackData table 背包数据
---@param part number 装备位置
function UICultivateEquipUpgradeLevelDialog:CalcEquipFoodExp(backpackData, part)
    local refId = backpackData.refId
    local partType = backpackData.partType
    local exp, goldExp = 0, 0
    if partType == EQUIP_TYPE.Equip then
        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(refId)
        local equipPart = equipVo.part
        ---@type EquipLevelConsumeVo
        local equipLevelConsumeVo = cardConfMgr:GetEquipLevelConsumeVo(equipVo.levelUpType, equipVo.rare, checkInt(backpackData.level))
        goldExp = equipLevelConsumeVo.offerNum
        exp = goldExp * ((part == equipPart) and 1.5 or 1)
    elseif partType == EQUIP_TYPE.Core then
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(refId)
        exp = equipCoreVo.expOffered
        goldExp = equipCoreVo.expOffered
    end

    return exp, goldExp
end

function UICultivateEquipUpgradeLevelDialog:CalcDogFoodExp(dogFoodData)
    ---@type EquipmentDogFoodVo
    local dogFoodVo = dogFoodData.dogFoodVo
    local goldExp = dogFoodVo.effectNum
    return goldExp * 1.5, goldExp
end

