---UpdateEquipExp
---@param backpackData table 背包数据
---@param isSelect boolean 是否选择
---@param isDisableCheck boolean 是否禁用检查
function UICultivateEquipUpgradeLevelDialog:UpdateEquipExp(backpackData, isSelect, isDisableCheck)
    local factor = isSelect and 1 or -1
    -- if isSelect and not isDisableCheck and self.arrivalsMaxLvNeedExp <= 0 then
    --     GameUtils.Toast(localize("已能到达最大等级"))
    --     return 0
    -- end

    local foodExp, goldExp = self:CalcEquipFoodExp(backpackData, self.equipPart)
    self.selectCount = self.selectCount + factor
    local deltaExp = foodExp * factor
    self.expAddition = self.expAddition + deltaExp
    self.consumeGoldAddition = self.consumeGoldAddition + goldExp * factor

    self.arrivalsMaxLvNeedExp = self.arrivalsMaxLvNeedExp + deltaExp * -1
    if not isDisableCheck then
        self:RefreshEquipExpInfo(self:GetEquipDojo(), factor)
        self:RefreshEquipAttributeNode(self:GetEquipDojo())
        self:RefreshEquipBottomNode()
    end

    -- ---@type UICultivateEquipLevelBackpackNodeMB
    -- local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
    -- if mbEnv == nil then return deltaExp end
    -- mbEnv:SetIsDisableUpdateSelectFood(self.arrivalsMaxLvNeedExp <= 0)
    return deltaExp
end


---UpdateEquipExp
---@param backpackData table 背包数据
---@param isSelect boolean 是否选择
---@param isDisableCheck boolean 是否禁用检查
function UICultivateEquipUpgradeLevelDialog:UpdateEquipExpByDogFood(isReduce, dogFoodData)
    if dogFoodData.ownNum <= 0 or (not isReduce and dogFoodData.ownNum == dogFoodData.selectNum) or (isReduce and dogFoodData.selectNum <= 0) then
        return false
    end
    local factor = isReduce and -1 or 1
    if not isReduce and self.arrivalsMaxLvNeedExp <= 0 then
        GameUtils.Toast(localize("已能到达最大等级"))
        return false
    end

    dogFoodData.selectNum = dogFoodData.selectNum + factor

    local exp, goldExp        = self:CalcDogFoodExp(dogFoodData)
    local deltaExp            = exp * factor
    self.expAddition          = self.expAddition + deltaExp
    self.consumeGoldAddition  = self.consumeGoldAddition + goldExp * factor
    
    self.arrivalsMaxLvNeedExp = self.arrivalsMaxLvNeedExp + deltaExp * -1
    ---@type EquipDojo
    local equipDojo = self:GetEquipDojo()
    self:RefreshEquipExpInfo(equipDojo, factor)
    self:RefreshEquipAttributeNode(equipDojo)
    self:RefreshEquipBottomNode()

    -- ---@type UICultivateEquipLevelBackpackNodeMB
    -- local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
    -- if not isNull(mbEnv) then 
    --     mbEnv:SetIsDisableUpdateSelectFood(self.arrivalsMaxLvNeedExp <= 0)
    -- end
    return true
end

function UICultivateEquipUpgradeLevelDialog:OnUpgradeButtonAction(eventData)
    local equipDojo = self:GetEquipDojo()
    if checkNumber(equipDojo.level) >= self.maxLevel then
        GameUtils.Toast(localize("已到达最大等级"))
        return
    end

    local consumeGoods = {}
    local commonEquipments = {}
    for i, v in ipairs(self.dogFoodInfo) do
        local selectNum = v.selectNum
        if selectNum > 0 then
            table.insert(commonEquipments, {goodsId = v.dogFoodVo.id, num = v.selectNum})
            table.insert(consumeGoods, {goodsId = v.dogFoodVo.id, num = -v.selectNum})
        end
    end

    if self.selectCount <= 0 and next(commonEquipments) == nil then
        GameUtils.Toast(localize('当前未选择材料'))
        return
    end

    local goldConsumeNum = self.consumeGoldAddition * self.consumeAspect
    if self.ownGoldNum < goldConsumeNum then
        local vo = goodsConfMgr:GetGoodsVoById(Constants.Currency.GoldId)
        GameUtils.Toast(localize('升级所需_name_不足', { _name_ = tostring(vo.name) }))
        return
    end

    ---@type UICultivateEquipLevelBackpackNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
    if mbEnv == nil then return end
    local selectFoods = mbEnv:GetSelectFoods()
    local isNeedSecondConfirm = false
    local purple = Constants.QualityType.Purple
    for key, conf in pairs(selectFoods) do
        local partType = conf.partType
        local id = conf.id
        local quality
        if partType == EQUIP_TYPE.Equip then
            local dojo = equipComp:GetEquipById(id)
            ---@type EquipVo
            local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
            quality = equipVo.rare
        else
            local dojo = equipComp:GetEquipCoreById(id)
            ---@type EquipCoreVo
            local equipCoreVo = cardConfMgr:GetEquipCoreVoById(dojo.equipmentCoreId)
            quality = equipCoreVo.quality
        end
        if quality >= purple then
            isNeedSecondConfirm = true
            break
        end
    end


    if isNeedSecondConfirm then
        GameUtils.SecondConfirm(localize("选择的有高品质情绪涂鸦，是否继续？"), function()
            self:ExecuteUpgradeLevelRequest(equipDojo, goldConsumeNum, selectFoods, commonEquipments, consumeGoods)
        end)
        return
    end
    self:ExecuteUpgradeLevelRequest(equipDojo, goldConsumeNum, selectFoods, commonEquipments, consumeGoods)
end


---ExecuteUpgradeLevelRequest
---执行升级请求的逻辑
---@param equipDojo EquipDojo
---@param goldConsumeNum number
function UICultivateEquipUpgradeLevelDialog:ExecuteUpgradeLevelRequest(equipDojo, goldConsumeNum, selectFoods, commonEquipments, consumeGoods)

    table.insert(consumeGoods, { goodsId = Constants.Currency.GoldId, num = -goldConsumeNum})

    local id2SuitIdMap, coreId2SuitIdMap = equipComp:GetId2SuitIdMap()

    local suitId2WaitRemoveEquip, suitId2WaitRemoveCore = {}, {}
    local foodEquipmentList = {}
    local foodEquipmentCoreList = {}
    for key, conf in pairs(selectFoods) do
        local partType = conf.partType
        local id = conf.id
        if partType == EQUIP_TYPE.Core then
            table.insert(foodEquipmentCoreList, id)
            local diySuitIdMap = coreId2SuitIdMap[tostring(id)]
            if diySuitIdMap then
                for i, diySuitId in pairs(diySuitIdMap) do
                    diySuitId = checkNumber(diySuitId)
                    suitId2WaitRemoveCore[diySuitId] = checkInt(id)
                end
            end
        elseif partType == EQUIP_TYPE.Equip then
            table.insert(foodEquipmentList, id)
            local diySuitIdMap = id2SuitIdMap[tostring(id)]
            if diySuitIdMap then
                for i, diySuitId in pairs(diySuitIdMap) do
                    diySuitId = checkNumber(diySuitId)
                    suitId2WaitRemoveEquip[diySuitId] = suitId2WaitRemoveEquip[diySuitId] or {}
                    id = checkInt(id)
                    suitId2WaitRemoveEquip[diySuitId][id] = id
                end
            end
        end


    end
    
    local requestData = {playerEquipmentId = tostring(equipDojo.id)}
    if next(foodEquipmentList) then
        requestData.foodEquipments = table.concat(foodEquipmentList, ',')
    end
    if next(foodEquipmentCoreList) then
        requestData.foodEquipmentCores = table.concat(foodEquipmentCoreList, ',')
    end

    if next(commonEquipments) then
        requestData.commonEquipments = table.serialize(commonEquipments)
    end


    GameUtils.Request(Interfaces.EquipmentLevelUp, requestData, function(req, responseTable)
        local code = checkNumber(responseTable.errCode)
        if code == 0 then
            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_zhuangbei)

            ---@type UICultivateEquipLevelBackpackNodeMB
            local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
            --------------------------
            --- update data
            local oldEquipDojo = clone(equipDojo)

            ---update backpack data
            if mbEnv then
                mbEnv:RemoveSuitDataPartListByIds(foodEquipmentList)
                mbEnv:RemoveSuitDataPartListByIds(foodEquipmentCoreList, -1)
            end

            local responseData = responseTable.data or {}
            local playerEquipment = checkTable(responseData.playerEquipment)
            equipDojo = equipComp:UpdateEquipDojoByServerData(equipDojo.id, playerEquipment)
            self:SetEquipDojo(equipDojo)
            GoodsUtils.DrawRewards(consumeGoods)

            equipComp:RemoveInlaidDiySuitEquip(suitId2WaitRemoveEquip, suitId2WaitRemoveCore)
            equipComp:RemoveEquipsByIdList(foodEquipmentList)
            equipComp:RemoveEquipCoresByIdList(foodEquipmentCoreList)

            for i, v in ipairs(self.dogFoodInfo) do
                v.ownNum = v.ownNum - v.selectNum
                v.selectNum = 0

                self:FreshDogFoodNodeSelectNum(i, v, true)
            end

            self.selectCount = 0
            --------------------------

            --------------------------
            --- update UI
            if mbEnv then
                mbEnv:ClearSelectData()
            end
            self:RefreshUI(true)

            if checkNumber(equipDojo.level) > checkNumber(oldEquipDojo.level) then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
                      oldEquipDojo = oldEquipDojo,
                      equipDojo    = equipDojo,
                      equipVo      = self.equipVo,
                      levelUpType = Constants.UICultivateLevelUpFinishType.Equip
                } })
            end

            --------------------------

        end
    end)

end

