--- OnFastSelectAction
---@param luaEnv UICultivateEquipSettingPanel
function UICultivateEquipUpgradeLevelDialog:OnFastSelectAction(luaEnv)
    local targetLevel, selectRule = luaEnv.targetLevel, luaEnv.selectRule
    if targetLevel <= self.nextLevel then
        return
    end
    
    if self.arrivalsMaxLvNeedExp <= 0 then
        GameUtils.Toast(localize("当前选择的涂鸦已达到最大等级"))
        return
    end

    local curSelectExp = self.baseExp + self.expAddition

    ---@type EquipVo
    local equipVo = self.equipVo
    local targetTotalExp = cardConfMgr:GetEquipExpByLevelId(equipVo.levelUpType, equipVo.rare, targetLevel).totalExp

    ---到达目标等级所需经验
    local arrivalsTargetLvNeedExp = targetTotalExp - curSelectExp

    --- 处理狗粮
    local foodRuleList = selectRule[Constants.EquipCultivateFastSelectFilterType.Food] or {}
    local isExistFoodCond = next(foodRuleList) ~= nil
    ---未选择材料类型 或者 选择了装备狗粮类型
    local isCanSelectEquip = not isExistFoodCond or table.keyof(foodRuleList, Constants.EquipCultivateFoodType.Equip) ~= nil
    local isCanSelectFood  = not isExistFoodCond or table.keyof(foodRuleList, Constants.EquipCultivateFoodType.DogFood) ~= nil
    
    local status
    if isCanSelectFood then
        local dogFoodInfo = self.dogFoodInfo
        for i, v in ipairs(dogFoodInfo) do
            local ownNum       = v.ownNum
            local selectNum    = v.selectNum
            --- 该狗粮剩余数量
            local remainingNum = ownNum - selectNum
            if remainingNum > 0 then
                ---@type EquipmentDogFoodVo
                -- local dogFoodVo = v.dogFoodVo
                -- local effectNum = dogFoodVo.effectNum * 1.5
                local effectNum  = self:CalcDogFoodExp(v)
                
                ---该狗粮最大需求数量
                local maxNeedNum = math.ceil(arrivalsTargetLvNeedExp / effectNum)
                ---该狗粮能提供的最大数量
                local provideNum = math.min(maxNeedNum, remainingNum)
                ---该狗粮能提供的最大经验
                local provideExp = provideNum * effectNum

                dogFoodInfo[i].selectNum = selectNum + provideNum

                self:FreshDogFoodNodeSelectNum(i, dogFoodInfo[i])

                self.expAddition = self.expAddition + provideExp
                self.consumeGoldAddition = self.consumeGoldAddition + provideExp
                self.arrivalsMaxLvNeedExp = self.arrivalsMaxLvNeedExp - provideExp
                status = 2
                arrivalsTargetLvNeedExp = arrivalsTargetLvNeedExp - provideExp
                if arrivalsTargetLvNeedExp <= 0 then
                    break
                end

            end

        end
    end

    if isCanSelectEquip then
        ---@type UICultivateEquipLevelBackpackNodeMB
        local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
        if mbEnv == nil then return end

        local status1 = mbEnv:FastSelectCells(function(backpackData)
            -- if arrivalsTargetLvNeedExp <= 0 or self.selectCount >= MaxSelectCount then
            if arrivalsTargetLvNeedExp <= 0 then
                return false
            end
            local deltaExp = self:UpdateEquipExp(backpackData, true, true)
            arrivalsTargetLvNeedExp = arrivalsTargetLvNeedExp - deltaExp
            return true
        end, selectRule)

        if status ~= 2 then
            status = status1
        end
    end


    local t = {
        localize("当前无涂鸦符合快速选择条件"),
        localize("涂鸦选择成功"),
    }

    local text = t[status]
    if text then
        GameUtils.Toast(text)
    end

    -- ---@type UICultivateEquipLevelBackpackNodeMB
    -- local mbEnv = CfUtils.GetLuaScr(self.EquipBackpackNode, EquipLevelBackpackNodeMBPath)
    -- if not isNull(mbEnv) then 
    --     mbEnv:SetIsDisableUpdateSelectFood(self.arrivalsMaxLvNeedExp <= 0)
    -- end

    --- 统一刷新一次
    self:RefreshEquipExpInfo(self:GetEquipDojo(), 1)
    self:RefreshEquipBottomNode()
    self:RefreshEquipAttributeNode(self:GetEquipDojo())
end

