end

function UICultivateEquipUpgradeLevelDialog:CreatePressCo()
    if self.co then return end
    local yield_return = cs_coroutine.yield_return
    
    self.co = cs_coroutine.start(function()
        xTry(function()
            while true do
                if self.isClick then
                    self:PressCell(self.downIndex, self.isReduce)

                    self.isClick = false
                    yield_return(DelayTime)
                end

                if self.isPress then
                    self:PressCell(self.downIndex, self.isReduce)
                end
                yield_return(DelayTime1)
            end

        end)
    end)
end

function UICultivateEquipUpgradeLevelDialog:PressCell(index, isReduce)
    local data = self.dogFoodInfo[index]
    local res  = self:UpdateEquipExpByDogFood(isReduce, data)
    if not res then
        return
    end
    self:FreshDogFoodNodeSelectNum(index, data)
end

function UICultivateEquipUpgradeLevelDialog:FreshDogFoodNodeSelectNum(index, data, isFreshUI)
    local node = self.dogFoodNodes[index]
    ---@type UICultivateEquipUpLevelDogFoodNode
    local env = CfUtils.GetLuaScr(node, DogFoodNodePath)
    if not isNull(env) then
        if isFreshUI then
            env:FreshUI(data, index)

        else
            env:FreshSelectState(data.selectNum)

        end
    end
end

function UICultivateEquipUpgradeLevelDialog:OnEventGuideCustomHandleStep()
    self:PressCell(3, false)
end

